import {CircuitViewer,paletteFor} from './circuit.js';
import {stopWindow,pitScenario,projectedClassification} from './strategy.js';
import {buildField, simulate, cleanLaps} from './model.js';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {season:2026, data:null, race:null, geometry:null, geo:null, forecast:[], telemetry:[], laps:[], view:'overview', token:'', liveTimer:null, replayTimer:null, positionEvents:[], drivers:[], mode:'replay', session:null, request:0, liveBusy:false};
const colors = {mercedes:'#36aaa1',mclaren:'#df9a52',ferrari:'#c97177',red_bull:'#7186b0',aston_martin:'#668f77',alpine:'#a78cba',williams:'#709bce',rb:'#8f99c4',racing_bulls:'#8f99c4',haas:'#9ba4ac',sauber:'#8aab69',audi:'#a87971',cadillac:'#a1a59b'};
const color = id => colors[id] || '#8899a7';
const teamStyle = t => `--team:${color(t)}`;
const flags={Mexico:'🇲🇽',Brazil:'🇧🇷',USA:'🇺🇸',Qatar:'🇶🇦',UAE:'🇦🇪',UK:'🇬🇧',Italy:'🇮🇹',Australia:'🇦🇺',China:'🇨🇳',Japan:'🇯🇵',Bahrain:'🇧🇭',Spain:'🇪🇸',Canada:'🇨🇦',Monaco:'🇲🇨',Austria:'🇦🇹',Belgium:'🇧🇪',Hungary:'🇭🇺',Netherlands:'🇳🇱',Azerbaijan:'🇦🇿',Singapore:'🇸🇬',Malaysia:'🇲🇾',Saudi_Arabia:'🇸🇦','Saudi Arabia':'🇸🇦'};
const titles={scenario:['One call changes everything.','A recorded race. Your strategy. Explore what could have happened.'],overview:['The grid. Decoded.','From the first sector to the final flag. See the race differently.'],predictions:['The race before the race.','Turn historical form into possibilities. Explore the next result.'],analysis:['Go beyond the result.','Sector by sector. Lap by lap. Find where the difference is made.'],standings:['The championship picture.','Every position matters. Every point tells part of the story.'],circuits:['Know every corner.','Explore the circuits that shape the championship.'],live:['Your seat on the pit wall.','Follow the running order and driver positions as the race unfolds.']};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500)}
async function fetchJSON(url, auth=false){const r=await fetch(url,{signal:AbortSignal.timeout(20000),headers:auth && state.token?{Authorization:`Bearer ${state.token}`}:{}});if(!r.ok)throw new Error(`Feed returned ${r.status}${r.status===401||r.status===403?' — check your OpenF1 subscription and token':''}`);return r.json()}
async function openF1(endpoint,params={},auth=false){return fetchJSON('https://api.openf1.org/v1/'+endpoint+'?'+new URLSearchParams(params),auth)}
function dialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#info-dialog').showModal()}
function showView(view){if(!titles[view])view='overview';state.view=view;document.body.dataset.view=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));$$('nav a').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#breadcrumb').textContent={scenario:'Strategy lab',overview:'Race weekend',predictions:'Race predictions',analysis:'Race analysis',standings:'Driver standings',circuits:'Circuit explorer',live:'Live race center'}[view];$('#page-title').textContent=titles[view][0];$('#page-subtitle').textContent=titles[view][1];if(location.hash!=='#'+view)history.replaceState(null,'','#'+view)}
function driverLabel(driver){return `${esc(driver.givenName)} ${esc(driver.familyName)}`}
function time(seconds){if(!Number.isFinite(seconds)||seconds<=0)return '—';return `${Math.floor(seconds/60)}:${(seconds%60).toFixed(3).padStart(6,'0')}`}
function snapshotStatus(label){$('#data-status').textContent=label}
async function init(){try{const [data,geo]=await Promise.all([fetchJSON('./data/2026.json'),fetchJSON('./data/circuits.geojson')]);state.geo=geo;applyData(data);showView(location.hash.slice(1));checkLatestRace();}catch(e){toast('Could not load the dataset. Refresh to try again.');snapshotStatus('Data unavailable');console.error(e)}}
function applyData(data,selectedRound){stopTracking();state.data=data;state.season=+data.season;const latest=data.races.at(-1);state.race=data.schedule.find(r=>r.round===selectedRound)||data.schedule.find(r=>r.round===latest?.round)||latest||data.schedule.at(-1);$('#race-select').innerHTML=data.schedule.map(r=>`<option value="${esc(r.round)}" ${r.round===state.race.round?'selected':''}>R${String(r.round).padStart(2,'0')} · ${esc(r.raceName.replace(' Grand Prix',''))}</option>`).join('');$('#standings-season').textContent=state.season;snapshotStatus(`Cached · ${new Date(data.fetchedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`);renderRace();renderStandings();}
function renderRace(){stopTracking();state.telemetry=[];state.laps=[];state.session=null;$('#telemetry-status').textContent='Load OpenF1 telemetry for best sectors and average clean race pace. Pit-out laps and laps outside 85–110% of median pace are excluded.';$('#lap-chart').innerHTML='';$('#load-telemetry').disabled=false;$('#load-telemetry').textContent='Load sector & lap data ↗';const r=state.race,c=r.Circuit,l=c.Location;$('#race-flag').textContent=flags[l.country]||'🏁';$('#race-title').textContent=r.raceName;$('#race-location').textContent=`${c.circuitName} · ${l.locality}, ${l.country}`;const date=new Date(r.date+'T12:00:00Z');$('#race-day').textContent=date.getUTCDate().toString().padStart(2,'0');$('#race-month').innerHTML=`${date.toLocaleString('en-US',{month:'long',timeZone:'UTC'}).toUpperCase()}<small>${state.season}</small>`;$('#race-round').textContent=`ROUND ${String(r.round).padStart(2,'0')} · ${new Date(r.date+'T23:59:59Z')>new Date()?'UPCOMING RACE':'HISTORICAL RACE'}`;$('#circuit-country').textContent=l.country.toUpperCase();$('#explorer-title').textContent=c.circuitName;findGeometry();renderTracks();runSimulation(false);renderMetrics();renderFormChart();renderAnalysis();resetLive();renderHome();setupScenario();}
function findGeometry(){const loc=state.race.Circuit.Location;const lat=+loc.lat,lng=+loc.long;const candidates=state.geo.features.filter(f=>f.geometry?.type==='LineString').map(f=>{const p=f.geometry.coordinates;const avg=p.reduce((a,c)=>[a[0]+c[0]/p.length,a[1]+c[1]/p.length],[0,0]);return {f,d:Math.hypot((avg[0]-lng)*Math.cos(lat*Math.PI/180),avg[1]-lat)}}).sort((a,b)=>a.d-b.d);state.geometry=candidates[0]?.d<.2?candidates[0].f:null;}
function trackSVG(large=false){const f=state.geometry;if(!f)return '<div class="empty">Track geometry is not yet available for this circuit.</div>';const coords=f.geometry.coordinates;const cos=Math.cos(coords[0][1]*Math.PI/180);const xy=coords.map(p=>[p[0]*cos,-p[1]]);const xs=xy.map(p=>p[0]),ys=xy.map(p=>p[1]);const minX=Math.min(...xs),minY=Math.min(...ys),w=Math.max(...xs)-minX,h=Math.max(...ys)-minY;const scale=Math.min(440/w,230/h);const points=xy.map(p=>[(p[0]-minX)*scale+ (560-w*scale)/2,(p[1]-minY)*scale+(300-h*scale)/2]);let svg=`<svg viewBox="0 0 560 300" role="img" aria-label="${esc(state.race.Circuit.circuitName)} track outline"><text x="280" y="165" text-anchor="middle" class="track-bg-label">${esc(state.race.Circuit.Location.country.toUpperCase())}</text>`;for(let i=0;i<3;i++){const start=Math.floor(i*(points.length-1)/3),end=Math.floor((i+1)*(points.length-1)/3);svg+=`<polyline points="${points.slice(start,end+1).map(p=>p.join(',')).join(' ')}" fill="none" stroke="${paletteFor(state.race.Circuit.Location.country)[i%paletteFor(state.race.Circuit.Location.country).length]}" stroke-width="${large?4:5}" stroke-linecap="round" stroke-linejoin="round"/>`;}const [x,y]=points[0];svg+=`<rect x="${x-4}" y="${y-4}" width="8" height="8" fill="#273132" stroke="#fff" stroke-width="2"/><text x="${x+12}" y="${y-8}" class="track-caption">START / FINISH</text><text x="280" y="294" text-anchor="middle" class="track-caption">GEOGRAPHIC LAYOUT / COUNTRY COLORS</text></svg>`;return svg;}
function runSimulation(notify=true){const weight=+$('#form-weight').value/100;const runs=+$('#sim-count').value;const {field,history}=buildField(state.data.races,state.race.round,weight);state.forecast=simulate(field,runs,+$('#variance').value);$('#simulation-caption').textContent=`${runs.toLocaleString()} simulated races · ${history.length} prior rounds`;$('#sim-badge').textContent=`${runs.toLocaleString()} RUNS`;$('#forecast-label').textContent=new Date(state.race.date+'T23:59:59Z')<new Date()?'Historical forecast · only pre-race inputs':'Pre-race forecast · recent form baseline';$('#model-summary').innerHTML=history.length?`<b>${field.length} drivers · ${history.length} prior races.</b><br>Recent finishes (${Math.round(weight*100)}% form weighting), season finishes, grid position, and constructor form. Random performance and retirement risk vary each run. These probabilities are experimental and uncalibrated.`:'No earlier race results in this season. Select a later round to build a forecast.';renderPredictions();renderMetrics();renderFormChart();if(notify)toast(`${runs.toLocaleString()} simulations complete. Forecast updated.`)}
function renderPredictions(){const rows=state.forecast;$('#prediction-list').innerHTML=rows.length?rows.slice(0,5).map((d,i)=>`<div class="prediction-row" style="${teamStyle(d.team.constructorId)}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="driver-initial">${esc(d.driver.code||d.driver.familyName.slice(0,3).toUpperCase())}</span><div class="prediction-info"><div class="driver-line"><span><span class="driver-name">${driverLabel(d.driver)}</span><span class="team-name">${esc(d.team.name)}</span></span><span class="prob">${d.win.toFixed(1)}<small>%</small></span></div><div class="prob-bar"><span style="--prob:${d.win}%"></span></div></div></div>`).join(''):'<div class="empty">Select a race with earlier results to create a forecast.</div>';$('#prediction-table').innerHTML=rows.map((d,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td><div class="table-driver" style="${teamStyle(d.team.constructorId)}"><strong>${driverLabel(d.driver)}</strong><span class="team-name">${esc(d.team.name)}</span></div></td><td>${d.win.toFixed(1)}%</td><td>${d.podium.toFixed(1)}%</td><td>${d.avgPosition.toFixed(1)}</td></tr>`).join('');}
function standingsRows(){return state.data.standings[0]?.DriverStandings||[]}
function renderStandings(){const rows=standingsRows();$('#mini-standings').innerHTML=rows.slice(0,4).map(d=>`<div class="mini-row" style="${teamStyle(d.Constructors[0]?.constructorId)}"><span class="rank">${String(d.position).padStart(2,'0')}</span><span class="team-stripe"></span><div><span class="driver-name">${driverLabel(d.Driver)}</span><span class="team-name">${esc(d.Constructors[0]?.name)}</span></div><span class="mini-points">${esc(d.points)}<small>PTS</small></span></div>`).join('');renderFullStandings()}
function renderFullStandings(){const search=$('#driver-search').value.toLowerCase();const rows=standingsRows();const max=+rows[0]?.points||1;$('#standings-table').innerHTML=rows.filter(d=>`${d.Driver.givenName} ${d.Driver.familyName} ${d.Constructors.map(t=>t.name).join(' ')}`.toLowerCase().includes(search)).map(d=>`<tr style="${teamStyle(d.Constructors[0]?.constructorId)}"><td>${String(d.position).padStart(2,'0')}</td><td><div class="table-driver"><strong>${driverLabel(d.Driver)}</strong><span class="team-name">${esc(d.Driver.code||'')} · #${esc(d.Driver.permanentNumber||'—')}</span></div></td><td>${esc(d.Constructors.map(t=>t.name).join(' / '))}</td><td>${esc(d.wins)}</td><td><div class="points-bar"><b>${esc(d.points)}</b><i style="--width:${+d.points/max*65}%"></i></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No drivers match your search.</td></tr>';}
function renderFormChart(){const history=state.data.races.filter(r=>+r.round<+state.race.round).slice(-5);const drivers=state.forecast.slice(0,3);$('#form-legend').innerHTML=drivers.map(d=>`<span style="${teamStyle(d.team.constructorId)}">${esc(d.driver.familyName)}</span>`).join('');if(!history.length){$('#form-chart').innerHTML='<div class="empty">No previous rounds to display.</div>';return;}const w=540,h=205,left=28,top=12,bottom=170;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Finishing positions for the top three forecast drivers across the previous five races">`;const positions=[1,5,10,15,20];const x=i=>left+i*(w-left-20)/Math.max(history.length-1,1);const y=p=>top+(p-1)/21*(bottom-top);for(const p of positions)svg+=`<line x1="${left}" y1="${y(p)}" x2="${w-10}" y2="${y(p)}" stroke="#eef1f2" stroke-dasharray="3 5"/><text x="4" y="${y(p)+3}" font-size="8" fill="#a0a9ae">P${p}</text>`;history.forEach((r,i)=>svg+=`<text x="${x(i)}" y="197" text-anchor="middle" font-size="8" fill="#9aa5ab">${esc(r.Circuit.Location.country==='USA'?r.raceName.replace(' Grand Prix',''):r.Circuit.Location.country)}</text>`);for(const d of drivers){const pts=history.map((r,i)=>{const result=r.Results.find(z=>z.Driver.driverId===d.id);return result?[x(i),y(+result.position),+result.position]:null}).filter(Boolean);svg+=`<polyline points="${pts.map(p=>p.slice(0,2).join(',')).join(' ')}" fill="none" stroke="${color(d.team.constructorId)}" stroke-width="2" stroke-linejoin="round"/>`;pts.forEach(p=>svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="white" stroke="${color(d.team.constructorId)}" stroke-width="2"><title>${esc(d.driver.familyName)}: P${p[2]}</title></circle>`)}svg+='</svg>';$('#form-chart').innerHTML=svg;}
function renderAnalysis(){const result=state.data.races.find(r=>r.round===state.race.round);if(!result){$('#analysis-table').innerHTML='<tr><td colspan="9" class="empty">This race has not been completed. Explore a previous round for results and telemetry.</td></tr>';return;}$('#analysis-table').innerHTML=result.Results.map(r=>{const ls=state.laps.filter(l=>String(l.driver_number)===String(r.number));const clean=cleanLaps(ls);const best=key=>{const v=ls.map(l=>l[key]).filter(x=>Number.isFinite(x)&&x>0);return v.length?Math.min(...v).toFixed(3):'—'};return `<tr><td>${esc(r.position)}</td><td><div class="table-driver" style="${teamStyle(r.Constructor.constructorId)}"><strong>${driverLabel(r.Driver)}</strong><span class="team-name">${esc(r.Constructor.name)} · ${esc(r.status)}</span></div></td><td>${esc(r.grid)}</td><td>${esc(r.FastestLap?.Time?.time||time(ls.length?Math.min(...ls.filter(l=>l.lap_duration>0).map(l=>l.lap_duration)):NaN))}</td><td>${clean.length?time(clean.reduce((s,l)=>s+l.lap_duration,0)/clean.length):'—'}</td><td>${best('duration_sector_1')}</td><td>${best('duration_sector_2')}</td><td>${best('duration_sector_3')}</td><td>${esc(r.points)}</td></tr>`}).join('');}
const sessionCache=new Map();
async function findSession(race=state.race){const year=+race.season||state.season;if(!sessionCache.has(year)){const sessions=await openF1('sessions',{year,session_name:'Race'});sessionCache.set(year,sessions);}const date=new Date(race.date+'T12:00:00Z').getTime();const sessions=sessionCache.get(year).filter(s=>s.session_type==='Race'&&!s.is_cancelled).map(s=>({s,delta:Math.abs(new Date(s.date_start).getTime()-date)})).sort((a,b)=>a.delta-b.delta);if(!sessions.length||sessions[0].delta>2*86400000)throw new Error('OpenF1 has no race session for this date. Try a completed race from 2024.');return sessions[0].s;}
async function loadTelemetry(){if(!state.data.races.some(r=>r.round===state.race.round)){toast('Select a completed race to load lap telemetry.');return;}const request=++state.request;const season=state.season,round=state.race.round;$('#load-telemetry').disabled=true;$('#telemetry-status').textContent='Finding session and loading OpenF1 laps…';try{const session=await findSession();const laps=await openF1('laps',{session_key:session.session_key});if(request!==state.request||season!==state.season||round!==state.race.round)return;if(!laps.length)throw new Error('No lap records available for this session.');state.session=session;state.laps=laps;renderAnalysis();renderLapChart();renderMetrics();$('#telemetry-status').textContent=`OpenF1 · ${session.session_name} · ${laps.length.toLocaleString()} lap records. Average pace excludes pit-out laps and laps outside 85–110% of each driver’s median. Best sectors may come from different laps.`;toast('Lap and sector analysis loaded.')}catch(e){if(request===state.request){$('#telemetry-status').textContent=`Telemetry unavailable: ${e.message}. Race results remain available.`;toast('Could not load telemetry. Race results are still available.')}}finally{if(request===state.request)$('#load-telemetry').disabled=false;}}
function renderLapChart(){const result=state.data.races.find(r=>r.round===state.race.round);const drivers=result.Results.slice(0,3);const series=drivers.map(d=>({d,laps:cleanLaps(state.laps.filter(l=>String(l.driver_number)===d.number))}));const all=series.flatMap(s=>s.laps);if(!all.length)return;const min=Math.min(...all.map(x=>x.lap_duration))-1,max=Math.max(...all.map(x=>x.lap_duration))+1,last=Math.max(...all.map(x=>x.lap_number));const x=n=>45+n/last*950,y=t=>170-(t-min)/(max-min)*145;let svg='<svg viewBox="0 0 1020 220" role="img" aria-label="Clean lap pace by lap number for the top three finishers">';for(let i=0;i<4;i++){const t=min+(max-min)*i/3;svg+=`<line x1="45" y1="${y(t)}" x2="1000" y2="${y(t)}" stroke="#edf1f2"/><text x="0" y="${y(t)+4}" font-size="10" fill="#8c989f">${t.toFixed(1)}s</text>`;}series.forEach((s,i)=>{const c=color(s.d.Constructor.constructorId);svg+=`<text x="${50+i*210}" y="210" fill="${c}" font-size="11">● ${esc(s.d.Driver.familyName)}</text><polyline fill="none" stroke="${c}" stroke-width="1.8" points="${s.laps.map(l=>`${x(l.lap_number)},${y(l.lap_duration)}`).join(' ')}"/>`});svg+='<text x="1000" y="210" text-anchor="end" fill="#95a0a6" font-size="10">LAP NUMBER →</text></svg>';$('#lap-chart').innerHTML=svg;}
function stopTracking(){clearInterval(state.liveTimer);clearInterval(state.replayTimer);state.liveTimer=null;state.replayTimer=null;state.liveGeneration=(state.liveGeneration||0)+1;state.request++;state.liveBusy=false;}
function resetLive(){state.mode='replay';state.positionEvents=[];$('#live-badge').textContent='REPLAY MODE';$('#live-session').textContent=state.race.raceName;$('#live-message').textContent='Replay uses recorded position changes from OpenF1, at 60× speed. Select a completed race and press Play replay. Live timing requires an OpenF1 subscription and access token.';$('#replay-play').textContent='▶ Play replay';$('#replay-play').disabled=false;$('#replay-clock').textContent='—';$('#timing-tower').innerHTML='<div class="empty">Load a race replay or connect a live session to see the running order.</div>';$('#location-label').textContent='CIRCUIT OUTLINE';$('#location-note').textContent='Circuit outline shown. Car markers appear only with actual timestamped location samples.';}
function tower(events,drivers,at){const latest=new Map();for(const e of events){if(new Date(e.date).getTime()<=at)latest.set(e.driver_number,e);}const rows=[...latest.values()].sort((a,b)=>a.position-b.position);$('#timing-tower').innerHTML=rows.length?rows.map(e=>{const d=drivers.find(x=>x.driver_number===e.driver_number);return `<div class="tower-row" style="--team:#${esc(d?.team_colour||'93a3aa')}"><b>${esc(e.position)}</b><span class="driver-name">${esc(d?.full_name||'Driver '+e.driver_number)}</span><span>#${esc(e.driver_number)}</span></div>`}).join(''):'<div class="empty">Waiting for recorded position changes…</div>';}
async function playReplay(){if(state.mode==='live'){stopTracking();resetLive();}if(state.replayTimer){clearInterval(state.replayTimer);state.replayTimer=null;$('#replay-play').textContent='▶ Resume replay';return;}if(state.positionEvents.length&&state.replayAt<state.replayEnd){startReplayTimer();return;}if(!state.data.races.some(r=>r.round===state.race.round)){toast('Select a completed race to replay.');return;}stopTracking();const generation=state.liveGeneration;$('#replay-play').disabled=true;$('#replay-play').textContent='Loading…';try{const session=await findSession();const [events,drivers]=await Promise.all([openF1('position',{session_key:session.session_key}),openF1('drivers',{session_key:session.session_key})]);if(generation!==state.liveGeneration)return;if(!events.length)throw new Error('No position records available.');events.sort((a,b)=>new Date(a.date)-new Date(b.date));state.positionEvents=events;state.drivers=drivers;state.replayAt=new Date(events[0].date).getTime();state.replayStart=state.replayAt;state.replayEnd=new Date(events.at(-1).date).getTime();state.session=session;$('#live-message').textContent='Historical replay · recorded position changes at 60× speed. The timing tower follows original timestamps. The track view shows geographic geometry; no synthetic car positions are drawn.';$('#live-badge').textContent='RECORDED REPLAY';startReplayTimer();}catch(e){if(generation===state.liveGeneration){toast(e.message);$('#replay-play').textContent='▶ Retry replay';}}finally{if(generation===state.liveGeneration)$('#replay-play').disabled=false;}}
function startReplayTimer(){$('#replay-play').textContent='Ⅱ Pause replay';const tick=()=>{tower(state.positionEvents,state.drivers,state.replayAt);const mins=Math.floor((state.replayAt-state.replayStart)/60000);$('#replay-clock').textContent=`+${mins} MIN · 60×`;state.replayAt+=15000;if(state.replayAt>state.replayEnd){clearInterval(state.replayTimer);state.replayTimer=null;$('#replay-play').textContent='↻ Replay again';$('#replay-clock').textContent='FINISHED';}};tick();state.replayTimer=setInterval(tick,250);}
function connectionDialog(){dialog('Connect your live pit wall',`<p>Live telemetry uses a paid <a href="https://openf1.org/auth.html" target="_blank" rel="noreferrer">OpenF1 subscription</a>. Supply an access token from your account to connect to the active session.</p><label for="live-token">OpenF1 access token</label><input id="live-token" type="password" autocomplete="off" placeholder="Paste your access token"><p>The token stays in this browser tab’s memory and is sent only to api.openf1.org. It is cleared when the page reloads. Tokens expire; reconnect with a fresh token when needed.</p><button id="save-token" class="button primary">Connect live session</button><button id="disconnect" class="button secondary">Disconnect</button><p id="connection-error" role="status"></p>`);$('#save-token').onclick=async()=>{const token=$('#live-token').value.trim();if(!token){$('#connection-error').textContent='Enter an OpenF1 token to continue.';return;}state.token=token;$('#save-token').disabled=true;$('#connection-error').textContent='Checking the active session…';try{await connectLive();$('#info-dialog').close();showView('live');}catch(e){state.token='';$('#connection-error').textContent=e.message;}finally{if($('#save-token'))$('#save-token').disabled=false;}};$('#disconnect').onclick=()=>{state.token='';stopTracking();resetLive();renderTracks();$('#info-dialog').close();toast('Live feed disconnected.');};}
async function connectLive(){const sessions=await openF1('sessions',{session_key:'latest'},true);const session=sessions.at(-1);if(!session)throw new Error('No current session was returned.');const now=Date.now();if(now<new Date(session.date_start).getTime()-300000||now>new Date(session.date_end).getTime()+600000)throw new Error('There is no active session right now. Use a historical replay between sessions.');const drivers=await openF1('drivers',{session_key:session.session_key},true);stopTracking();state.mode='live';state.session=session;state.drivers=drivers;state.livePositions=new Map();state.liveLocations=new Map();state.liveTrails=new Map();state.liveSince=null;$('#live-badge').textContent='LIVE · OPENF1';$('#live-session').textContent=`${session.country_name} · ${session.session_name}`;$('#live-message').textContent='Connected to OpenF1. Timing and location refresh every 10 seconds. Telemetry coordinates are plotted directly; trails show recent movement.';$('#replay-play').textContent='▶ Switch to replay';if(await pollLive())state.liveTimer=setInterval(pollLive,10000);}
async function pollLive(){if(state.liveBusy||state.mode!=='live')return;state.liveBusy=true;const generation=state.liveGeneration;try{const params={session_key:state.session.session_key};if(state.liveSince)params['date>=']=state.liveSince;const [positions,locations]=await Promise.all([openF1('position',params,true),openF1('location',{...params,'date>=':new Date(Date.now()-15000).toISOString()},true)]);if(generation!==state.liveGeneration)return;positions.sort((a,b)=>new Date(a.date)-new Date(b.date));locations.sort((a,b)=>new Date(a.date)-new Date(b.date));for(const p of positions)state.livePositions.set(p.driver_number,p);for(const l of locations){state.liveLocations.set(l.driver_number,l);const trail=state.liveTrails.get(l.driver_number)||[];trail.push(l);state.liveTrails.set(l.driver_number,trail.slice(-300));}state.liveSince=new Date(Date.now()-15000).toISOString();tower([...state.livePositions.values()],state.drivers,Date.now());renderLocations();$('#replay-clock').textContent=new Date().toLocaleTimeString();$('#live-message').textContent=`OpenF1 live feed · last successful update ${new Date().toLocaleTimeString()}. Updates every 10 seconds.`;return true;}catch(e){if(generation===state.liveGeneration){clearInterval(state.liveTimer);state.liveTimer=null;$('#live-badge').textContent='FEED INTERRUPTED';$('#live-message').textContent=`Live feed interrupted: ${e.message}. Values below are stale. Reconnect to resume.`;toast('Live feed interrupted. Reconnect to resume.');}}finally{if(generation===state.liveGeneration)state.liveBusy=false;}}
function renderLocations(){const positions=[...state.liveLocations.values()].filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(!positions.length){$('#live-track').innerHTML='<div class="empty">Waiting for location samples from the active session.</div>';return;}const trails=[...state.liveTrails.values()].flat().filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));const xs=trails.map(p=>p.x),ys=trails.map(p=>p.y);const minX=Math.min(...xs),minY=Math.min(...ys),width=Math.max(...xs)-minX||1,height=Math.max(...ys)-minY||1;const scale=Math.min(460/width,270/height);const x=v=>50+(v-minX)*scale,y=v=>310-(v-minY)*scale;let svg='<svg viewBox="0 0 560 360" role="img" aria-label="Actual driver positions in OpenF1 telemetry coordinates">';state.liveTrails.forEach((trail,number)=>{const d=state.drivers.find(d=>d.driver_number===number);svg+=`<polyline points="${trail.filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)).map(p=>`${x(p.x)},${y(p.y)}`).join(' ')}" fill="none" stroke="#${esc(d?.team_colour||'aab5aa')}" stroke-width="1.5" opacity=".35"/>`});positions.forEach(p=>{const d=state.drivers.find(d=>d.driver_number===p.driver_number);svg+=`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="5" fill="#${esc(d?.team_colour||'aab5aa')}" class="live-marker"><title>${esc(d?.full_name||p.driver_number)}</title></circle><text x="${x(p.x)+8}" y="${y(p.y)-7}" font-size="10" fill="#66757b">${esc(d?.name_acronym||p.driver_number)}</text>`});svg+='</svg>';$('#live-track').innerHTML=svg;$('#location-label').textContent='ACTUAL TELEMETRY X / Y';$('#location-note').textContent='Dots are actual timestamped driver locations. Trails cover recent samples. Coordinates auto-fit the available telemetry; this is separate from the geographic circuit outline.';}
async function refreshData(){const season=state.season,round=state.race.round;const followLatest=round===state.data.races.at(-1)?.round;$('#refresh').disabled=true;$('#refresh').classList.add('busy');snapshotStatus('Refreshing feeds…');try{const base=`https://api.jolpi.ca/ergast/f1/${season}/`;const [schedule,standings,first]=await Promise.all([fetchJSON(base+'?limit=100'),fetchJSON(base+'driverstandings/?limit=100'),fetchJSON(base+'results/?limit=100')]);const all=[...first.MRData.RaceTable.Races];const total=+first.MRData.total;for(let offset=100;offset<total;offset+=100){const page=await fetchJSON(base+`results/?limit=100&offset=${offset}`);all.push(...page.MRData.RaceTable.Races);}if(state.season!==season)return;const map=new Map();for(const race of all){if(map.has(race.round))map.get(race.round).Results.push(...race.Results);else map.set(race.round,race);}const races=[...map.values()].sort((a,b)=>+a.round-+b.round);const data={season,fetchedAt:new Date().toISOString(),races,schedule:schedule.MRData.RaceTable.Races,standings:standings.MRData.StandingsTable.StandingsLists};if(!data.schedule.length)throw new Error('The schedule feed was empty.');applyData(data,followLatest?undefined:round);snapshotStatus('Updated just now · Jolpica');toast('Race data and standings updated.');}catch(e){snapshotStatus('Cached data · refresh unavailable');toast('Feed unavailable. Keeping the complete cached dataset.');}finally{$('#refresh').disabled=false;$('#refresh').classList.remove('busy');}}
function methodology(){dialog('Inside the APEX forecast',`<p>APEX is an experimental Monte Carlo baseline, not a trained machine learning model. Each simulation ranks drivers by form plus random race-day variation.</p><p><b>Inputs:</b> 72% finishing form (your slider blends the last five results with season results), 18% recent starting grid, and 10% constructor finishing form. Retirement risk starts at 2.5%, adjusted by recent non-finishes.</p><p><b>No future results:</b> the selected race and later rounds are excluded. Historical races therefore show a pre-race forecast. Championship standings always show the latest available season table.</p><p><b>Limitations:</b> no weather, tyre strategy, current qualifying, circuit-specific fit, or regulation-change adjustment. Probabilities are uncalibrated. They describe the model’s simulations, not validated real-world odds.</p><p>Average race pace uses OpenF1 lap records, excluding pit-out laps and laps outside 85–110% of the driver’s median. Best sectors are individual minima and may come from different laps.</p>`)}
function sources(){dialog('Race data, with a clear provenance',`<p><a href="https://github.com/jolpica/jolpica-f1/blob/main/docs/README.md" target="_blank" rel="noreferrer">Jolpica F1</a> provides calendars, positions, fastest laps and championship standings. Cached snapshots include complete paginated results for the available 2024 and 2026 seasons. Refresh data requests the provider’s latest records.</p><p><a href="https://openf1.org/docs/" target="_blank" rel="noreferrer">OpenF1</a> provides race laps, sector times, position changes, and location samples from 2023 onward. Historical access is free; live access needs a subscription.</p><p>Geographic track outlines come from <a href="https://github.com/bacinger/f1-circuits" target="_blank" rel="noreferrer">f1-circuits</a> (MIT). Circuit colors follow the host country palette, rather than official timing-sector boundaries. The 3D mesh uses geographic coordinates with illustrative depth; it does not contain measured elevation. Older geometry may differ from a circuit’s current layout.</p><p>Missing values appear as “—”. No generated lap times or driver coordinates are presented as measured telemetry.</p>`)}
$$('nav a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showView(a.dataset.view)}));$$('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));$('#race-select').onchange=()=>{state.race=state.data.schedule.find(r=>r.round===$('#race-select').value);renderRace();};$('#season').onchange=async()=>{const season=+$('#season').value;stopTracking();try{const data=await fetchJSON(`./data/${season}.json`);if(+$('#season').value===season)applyData(data);}catch(e){$('#season').value=state.season;toast('Season dataset unavailable.');}};$('#run-top').onclick=()=>showView('scenario');$('#simulate').onclick=()=>{const b=$('#simulate');b.disabled=true;b.textContent='Simulating…';setTimeout(()=>{try{runSimulation();}finally{b.disabled=false;b.textContent='◈ Run simulation';}},40)};$('#form-weight').oninput=()=>$('#form-value').textContent=$('#form-weight').value+'%';$('#variance').oninput=()=>$('#variance-value').textContent=+$('#variance').value<4?'Low':+$('#variance').value>7?'High':'Medium';$('#method-link').onclick=e=>{e.preventDefault();methodology()};$('#method-open').onclick=methodology;$('#source-open').onclick=sources;$('#dialog-close').onclick=()=>$('#info-dialog').close();$('#settings').onclick=connectionDialog;$('#connect-live').onclick=connectionDialog;$('#replay-play').onclick=playReplay;$('#driver-search').oninput=renderFullStandings;$('#load-telemetry').onclick=loadTelemetry;$('#refresh').onclick=refreshData;window.addEventListener('hashchange',()=>showView(location.hash.slice(1)));window.addEventListener('pagehide',()=>{stopTracking();circuitViewers.forEach(v=>v.dispose())});

function renderMetrics(){
 const race=state.data.races.find(r=>r.round===state.race.round),results=race?.Results||[];
 const winner=results[0],fastest=results.filter(r=>r.FastestLap?.Time?.time).sort((a,b)=>+a.FastestLap.rank-+b.FastestLap.rank)[0];
 const clean=winner?cleanLaps(state.laps.filter(l=>String(l.driver_number)===String(winner.number))):[];
 const count=results.filter(r=>r.status==='Finished'||r.status==='Lapped'||/^\+\d+ Lap/.test(r.status)).length;
 const metrics=[['RACE WINNER',winner?esc(winner.Driver.familyName):'—',winner?`${esc(winner.Constructor.name)} · <b>+${winner.points} points</b>`:'Race results pending','⚑'],['FASTEST LAP',fastest?esc(fastest.FastestLap.Time.time):'—',fastest?`${esc(fastest.Driver.familyName)} · lap ${esc(fastest.FastestLap.lap)}`:'Not yet available','◷'],['WINNER’S RACE TIME',winner?esc(winner.Time?.time||'—'):'—',clean.length?`Clean average pace · <b>${time(clean.reduce((a,l)=>a+l.lap_duration,0)/clean.length)}</b>`:'Explore lap and sector data below','⌁'],['CLASSIFIED FINISHERS',results.length?`${count}<small>/ ${results.length} drivers</small>`:'—',race?`${Math.max(...results.map(r=>+r.laps))} laps · ${state.season} season`:'Select a completed race','▤']];
 $('#metrics').innerHTML=metrics.map(([label,value,foot,icon])=>`<div class="metric"><div class="metric-label">${label}<span>${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`).join('');
}
function renderHome(){const r=state.race;const results=state.data.races.find(x=>x.round===r.round)?.Results||[];const latest=state.data.races.at(-1)?.round===r.round;$('#race-title').innerHTML=esc(r.raceName).replace(' Grand Prix','<br>Grand Prix')+'<span>.</span>';$('#race-round').textContent=`${latest?'LATEST RACE':results.length?'RACE ARCHIVE':'UPCOMING RACE'} / ROUND ${String(r.round).padStart(2,'0')}`;$('#hero-country-name').textContent=r.Circuit.Location.country==='USA'?'UNITED STATES':r.Circuit.Location.country.toUpperCase();$('#country-watermark').textContent={USA:'USA',UK:'GBR','Saudi Arabia':'KSA'}[r.Circuit.Location.country]||r.Circuit.Location.country.slice(0,3).toUpperCase();$('#hero-date').textContent=new Date(r.date+'T12:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric',timeZone:'UTC'}).toUpperCase();$('#race-state').textContent=results.length?'✓ RACE COMPLETE':'UPCOMING RACE';$('#hero-circuit-name').textContent=r.Circuit.circuitName.toUpperCase();$('#hero-track-length').textContent=state.geometry?.properties?.length?(state.geometry.properties.length/1000).toFixed(3)+' KM':'LAYOUT PENDING';$('#hero-laps').textContent=results.length?Math.max(...results.map(r=>+r.laps))+' LAPS':'RACE DISTANCE TBC';$('#national-colors').innerHTML=paletteFor(r.Circuit.Location.country).map(c=>`<i style="background:${c}"></i>`).join('');$('#podium').innerHTML=results.length?results.slice(0,3).map(d=>`<div class="podium-row" style="${teamStyle(d.Constructor.constructorId)}"><span class="podium-rank">${String(d.position).padStart(2,'0')}</span><div class="podium-driver"><strong>${driverLabel(d.Driver)}</strong><small>${esc(d.Constructor.name)}</small></div><div class="podium-time">${esc(d.Time?.time||d.status)}<small>${esc(d.points)} POINTS</small></div></div>`).join(''):'<div class="empty">The podium will appear after the race.</div>';$('#home-classification').innerHTML=results.length?results.slice(0,6).map(d=>`<tr><td>${String(d.position).padStart(2,'0')}</td><td><div class="table-driver" style="${teamStyle(d.Constructor.constructorId)}"><strong>${driverLabel(d.Driver)}</strong></div></td><td>${esc(d.Constructor.name)}</td><td>${esc(d.Time?.time||d.status)}</td><td>${esc(d.FastestLap?.Time?.time||'—')}</td><td>${esc(d.points)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">Race results pending.</td></tr>';}
let circuitViewers=[];
function renderTracks(){circuitViewers.forEach(v=>v.dispose());circuitViewers=[];const fallback=trackSVG();$('#live-track').innerHTML=fallback;for(const id of ['overview-track','explorer-track']){const container=$('#'+id);container.removeAttribute('data-fallback');circuitViewers.push(new CircuitViewer(container,state.geometry,state.race.Circuit.Location.country,fallback));}const g=state.geometry?.properties;const result=state.data.races.find(x=>x.round===state.race.round);const laps=result?.Results.reduce((m,x)=>Math.max(m,+x.laps),0);const stats=`<div><small>CIRCUIT LENGTH</small><b>${g?.length?(g.length/1000).toFixed(3):'—'}<span>km</span></b></div><div><small>${laps?'RACE LAPS':'FIRST GRAND PRIX'}</small><b>${laps||g?.firstgp||'—'}</b></div><div><small>ALTITUDE</small><b>${g?.altitude??'—'}<span>m</span></b></div>`;$('#circuit-stats').innerHTML=stats;$('#explorer-stats').innerHTML=stats;}
const pitCache=new Map();
let scenarioVersion=0,scenarioStops=[],scenarioResults=[];
function clearScenario(message='Choose a driver and pit stop to explore an alternative.'){$('#scenario-result').innerHTML=`<div class="empty">${esc(message)}</div>`;$('#scenario-chart').innerHTML='';$('#scenario-table').innerHTML='';$('#scenario-explanation').textContent='';}
async function setupScenario(){const version=++scenarioVersion;scenarioStops=[];scenarioResults=state.data.races.find(r=>r.round===state.race.round)?.Results||[];$('#scenario-driver').innerHTML='';$('#scenario-stop').innerHTML='';$('#run-scenario').disabled=true;$('#original-lap').textContent='L—';$('#target-lap-label').textContent='L—';$('#target-lap').disabled=true;$$('[data-shift]').forEach(b=>b.disabled=true);clearScenario();$('#old-deg').value='.07';$('#new-deg').value='.05';$('#fresh-advantage').value='.8';$('#pit-delta').value='0';if(!scenarioResults.length){$('#scenario-data-note').textContent='Select a completed race to change a recorded strategy.';clearScenario('This race has not happened yet. Select a completed race.');return;}$('#scenario-data-note').textContent='Loading recorded pit stops…';try{const season=state.season,round=state.race.round;if(!pitCache.has(season))pitCache.set(season,await fetchJSON(`./data/pits-${season}.json`));if(version!==scenarioVersion)return;let pits=pitCache.get(season).races[round];if(!pits){const remote=await fetchJSON(`https://api.jolpi.ca/ergast/f1/${season}/${round}/pitstops/?limit=100`);pits=remote.MRData.RaceTable.Races[0]?.PitStops||[];}if(version!==scenarioVersion)return;scenarioStops=pits;const maxLaps=Math.max(...scenarioResults.map(r=>+r.laps));const drivers=scenarioResults.filter(r=>r.status==='Finished'&&+r.laps===maxLaps&&+r.Time?.millis>0&&pits.some(p=>p.driverId===r.Driver.driverId));if(!drivers.length){$('#scenario-data-note').textContent='No comparable lead-lap finishers with recorded pit stops are available for this race.';clearScenario('No recorded strategy can be modeled for this race. Try another completed round.');return;}$('#scenario-driver').innerHTML=drivers.map(r=>`<option value="${esc(r.Driver.driverId)}">${driverLabel(r.Driver)} · P${r.position}</option>`).join('');$('#scenario-data-note').textContent=`Recorded stops: Jolpica. ${drivers.length} lead-lap finishers available. Pit-lane duration is elapsed lane time, not time lost versus staying on track.`;$('#run-scenario').disabled=false;$('#target-lap').disabled=false;selectScenarioDriver();}catch(e){if(version===scenarioVersion){$('#scenario-data-note').textContent='Pit-stop feed unavailable. Recorded race results are still available.';clearScenario('Recorded pit stops could not be loaded. Select another race or refresh.');}}}
function selectedStops(){return scenarioStops.filter(p=>p.driverId===$('#scenario-driver').value).sort((a,b)=>+a.lap-+b.lap)}
function selectScenarioDriver(){const stops=selectedStops();$('#scenario-stop').innerHTML=stops.map((p,i)=>`<option value="${i}">Stop ${p.stop} · lap ${p.lap} · ${p.duration}s in lane</option>`).join('');selectScenarioStop();}
function selectScenarioStop(){const stops=selectedStops();if(!stops.length)return;const r=scenarioResults.find(r=>r.Driver.driverId===$('#scenario-driver').value);const w=stopWindow(stops,+$('#scenario-stop').value,+r.laps);$('#target-lap').min=w.min;$('#target-lap').max=w.max;$('#target-lap').value=w.original;$('#original-lap').textContent='L'+w.original;$('#target-lap').dataset.original=w.original;$('#pit-delta').value='0';updateScenarioLap();runScenario(false);}
function updateScenarioLap(){const target=+$('#target-lap').value,original=+$('#target-lap').dataset.original;$('#target-lap-label').textContent='L'+target;const shift=target-original;$('#lap-offset').textContent=shift===0?'Recorded lap':`${Math.abs(shift)} lap${Math.abs(shift)===1?'':'s'} ${shift>0?'later':'earlier'}`;$$('[data-shift]').forEach(b=>{const candidate=original+ +b.dataset.shift;b.disabled=candidate<+$('#target-lap').min||candidate>+$('#target-lap').max;b.classList.toggle('active',shift===+b.dataset.shift)});$('#scenario-explanation').textContent='Inputs changed. Run the simulation to update the estimated outcome.';}
function runScenario(notify=true){if(!selectedStops().length)return;try{for(const id of ['old-deg','new-deg','fresh-advantage','pit-delta'])if(!$('#'+id).reportValidity())return;const driverId=$('#scenario-driver').value;const result=scenarioResults.find(r=>r.Driver.driverId===driverId);const scenario=pitScenario({stops:selectedStops(),index:+$('#scenario-stop').value,totalLaps:+result.laps,targetLap:+$('#target-lap').value,oldDegradation:+$('#old-deg').value,newDegradation:+$('#new-deg').value,freshAdvantage:+$('#fresh-advantage').value,pitLossDelta:+$('#pit-delta').value});const classification=projectedClassification(scenarioResults,driverId,scenario.delta);const change=+result.position-classification.position;const signed=n=>n>0?'+'+n.toFixed(2):n.toFixed(2);$('#scenario-result').innerHTML=`<p class="scenario-name"><b>${driverLabel(result.Driver)}</b> · stop ${selectedStops()[+$('#scenario-stop').value].stop} moved from L${scenario.window.original} to L${scenario.targetLap}</p><div class="scenario-deltas"><div><small>RECORDED FINISH</small><b>P${result.position}</b><span>Official classification</span></div><div><small>ESTIMATED FINISH</small><b class="result-improvement">P${classification.position}</b><span>${change>0?'↑ '+change+' position'+(change===1?'':'s'):change<0?'↓ '+Math.abs(change)+' position'+(change===-1?'':'s'):'Position unchanged'}</span></div><div><small>RACE TIME CHANGE</small><b class="result-improvement">${signed(scenario.delta)}<small style="display:inline;font-size:16px;letter-spacing:0">s</small></b><span>${scenario.delta<0?'Estimated time gained':scenario.delta>0?'Estimated time lost':'Same recorded strategy'}</span></div></div>`;$('#scenario-explanation').textContent=`Model: old tyres +${(+$('#old-deg').value).toFixed(2)} s/lap of age; new tyres +${(+$('#new-deg').value).toFixed(2)} s/lap of age; fresh-tyre advantage ${(+$('#fresh-advantage').value).toFixed(1)} s. Sum the tyre-age cost difference from lap ${scenario.window.previous+1} through ${scenario.window.next}, then add ${signed(+$('#pit-delta').value)} s extra pit time. All other finish times are held fixed.`;$('#scenario-table').innerHTML=classification.rows.map(d=>`<tr class="${d.result.Driver.driverId===driverId?'selected':''}"><td>P${d.result.position}</td><td><strong>P${d.position}</strong></td><td><div class="table-driver" style="${teamStyle(d.result.Constructor.constructorId)}"><strong>${driverLabel(d.result.Driver)}</strong><span class="team-name">${esc(d.result.Constructor.name)}</span></div></td><td class="${d.change?'position-up':''}">${d.change>0?'↑ '+d.change:d.change<0?'↓ '+Math.abs(d.change):'—'}</td></tr>`).join('');renderScenarioChart(scenario);if(notify)toast('Alternative strategy calculated. Official results are preserved.');}catch(e){toast(e.message)}}
function renderScenarioChart(scenario){const data=scenario.timeline,max=Math.max(1,...data.map(x=>Math.abs(x.delta)))*1.15;const first=data[0].lap,last=data.at(-1).lap;const x=l=>40+(l-first)/Math.max(1,last-first)*640,y=d=>65-d/max*48;let svg='<svg viewBox="0 0 710 150" role="img" aria-label="Cumulative modeled tyre pace difference. Negative means time gained.">';svg+=`<line x1="40" x2="685" y1="65" y2="65" stroke="#dde1e6" stroke-dasharray="4 4"/><text x="4" y="68" font-size="8" fill="#9ca4af">0 s</text><polyline fill="none" stroke="#df3235" stroke-width="2" points="${data.map(d=>`${x(d.lap)},${y(d.delta)}`).join(' ')}"/>`;for(const lap of [first,scenario.window.original,scenario.targetLap,last])svg+=`<line x1="${x(lap)}" x2="${x(lap)}" y1="13" y2="118" stroke="#e9ebee" stroke-dasharray="2 4"/><text x="${x(lap)}" y="133" text-anchor="middle" fill="#a2a9b3" font-size="8">L${lap}</text>`;svg+='<text x="40" y="147" fill="#a0a7b1" font-size="7">CUMULATIVE MODELED PACE DIFFERENCE · NEGATIVE = TIME GAINED</text></svg>';$('#scenario-chart').innerHTML=svg;}
function strategyMethod(){dialog('Changing the call',`<p>The simulator uses a recorded pit stop and official finishing times. Moving a stop changes the tyre age on every lap up to the next recorded stop or the finish.</p><p>Lap cost before the stop is <b>old-tyre degradation × tyre age</b>. After the stop it is <b>− fresh-tyre advantage + new-tyre degradation × tyre age</b>. The alternative’s costs are compared with the same model at the recorded pit lap. Only the difference is applied to the selected driver’s recorded finish time.</p><p>You can adjust all three tyre assumptions and add extra pit time. The recorded lane duration is displayed for reference; it is not treated as an estimate of pit-stop time loss. Moving a stop keeps its total loss unchanged unless you explicitly change it.</p><p>Only lead-lap finishers with recorded times and stops can be selected. Opponents’ times remain fixed; lapped drivers and retirements keep their classifications. Strategies cannot cross another recorded stop. The model does not predict overtaking or account for weather, traffic, safety cars or reaction strategies. Results are conditional estimates, not reconstructed alternative history.</p>`)}
$('#scenario-driver').onchange=selectScenarioDriver;$('#scenario-stop').onchange=selectScenarioStop;$('#target-lap').oninput=updateScenarioLap;$('#run-scenario').onclick=()=>runScenario();$('#reset-scenario').onclick=()=>{for(const [id,v] of [['old-deg','.07'],['new-deg','.05'],['fresh-advantage','.8'],['pit-delta','0']])$('#'+id).value=v;selectScenarioStop()};$$('[data-shift]').forEach(b=>b.onclick=()=>{$('#target-lap').value=+$('#target-lap').dataset.original + +b.dataset.shift;updateScenarioLap()});$$('.assumptions input').forEach(i=>i.oninput=()=>{$('#scenario-explanation').textContent='Assumptions changed. Run the simulation to update the estimate.'});$('#strategy-method').onclick=strategyMethod;$$('[data-camera]').forEach(b=>b.onclick=()=>{const viewer=circuitViewers[state.view==='circuits'?1:0];viewer?.setView(b.dataset.camera==='top');b.parentElement.querySelectorAll('[data-camera]').forEach(x=>x.classList.toggle('active',x===b))});$$('[data-zoom]').forEach(b=>b.onclick=()=>circuitViewers[state.view==='circuits'?1:0]?.zoom(b.dataset.zoom==='in'?.82:1.22));$('#latest-race').onclick=()=>{const last=state.data.races.at(-1);if(last){state.race=state.data.schedule.find(r=>r.round===last.round)||last;$('#race-select').value=last.round;renderRace();showView('overview')}};

init();

async function checkLatestRace(){const season=state.season,round=state.race.round;try{const response=await fetchJSON(`https://api.jolpi.ca/ergast/f1/${season}/last/results/?limit=100`);const last=response.MRData.RaceTable.Races[0];if(state.season===season&&state.race.round===round&&+last?.round>+state.data.races.at(-1)?.round)await refreshData();}catch{/* Cached snapshot stays usable when the latest-result feed is unavailable. */}}
